import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def queries(ctx):
    features = torch.randn(4, 2, generator=ctx.rng.torch)
    targets = torch.tensor([0.0, 1.0, 2.0, 1.0])
    return {"inputs": synth.Tensor(features), "targets": synth.Tensor(targets)}
class RankingModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.scorer = build("mlp", "tiny", in_features=2, out_features=1)
    def forward(self, inputs):
        scores = self.scorer(inputs.reshape(-1, inputs.shape[-1])).squeeze(-1)
        return {"scores": scores.reshape(inputs.shape[:-1])}
dataset = synth.Spec("lambda-loss-queries", generator=queries, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
trainer = Trainer(RankingModel(), train, recipe="structured-objective", recipe_config={"loss": "lambda-loss", "loss_kwargs": {"sigma": 1.0, "reduction": "mean"}, "bindings": {"logits_or_prediction": {"output": "scores"}, "targets": {"batch": "targets"}}}, batch_size=2, max_epochs=1, device="cpu")
trainer.fit()
